public Line2DBase(PointF p1, float vx, float vy, Pen pen)
        {
            this.Pen = pen;
            if (vx == 0.0f && vy == 0.0f)
            {
                throw new ArithmeticException("Points are equals");
            }
            else
            {
                Point1 = p1;
                Point2 = new PointF(p1.X + vx, p1.Y + vy);
            }
        }

